const items = $input.all();
const results = [];
for (const item of items) {
  const fields = item.json;
  for (let i = 1; i <= 10; i++) {
    const id = fields[`編號${i}`];
    if (id && typeof id === 'string' && id.trim() !== "") {
      results.push({ json: { "有效客戶編號": id.trim() } });
    }
  }
}
if (results.length === 0) return [{ json: { "有效客戶編號": "NONE", "未綁定": true } }];
return results;

const input = $input.first().json;
const clients = Array.isArray(input['客戶名稱']) ? input['客戶名稱'] : [];
const amounts = Array.isArray(input['帳單金額']) ? input['帳單金額'] : [];
const statuses = Array.isArray(input['狀態']) ? input['狀態'] : [];
const links = Array.isArray(input['JPG連結']) ? input['JPG連結'] : [];
const changeTimes = Array.isArray(input['變更時間']) ? input['變更時間'] : [];
const bankAccountRaw = Array.isArray(input['匯款帳號']) ? input['匯款帳號'][0] : input['匯款帳號'];

const formatPrice = (v) => (v === undefined || v === null || v === '' || isNaN(parseFloat(v))) ? '--' : parseFloat(v).toLocaleString('en-US');
const parseMs = (s) => {
  const str = String(s || '').trim();
  let m = str.match(/(\d{1,2})\/(\d{1,2})\s+(\d{1,2}):(\d{1,2})修改/);
  if (m) return new Date(new Date().getFullYear(), +m[1]-1, +m[2], +m[3], +m[4]).getTime();
  m = str.match(/修改(?:\d+_)?(\d{2})(\d{2})-(\d{2})(\d{2})/);
  if (!m) return 0;
  return new Date(new Date().getFullYear(), +m[1]-1, +m[2], +m[3], +m[4]).getTime();
};

let total = 0, latestMs = 0, anyNotIssued = false, anyModifying = false;
const times = [], downloadable = [];
for (let j = 0; j < clients.length; j++) {
  const amt = amounts[j], link = String(links[j]||'').trim(), st = String(statuses[j]||'').trim(), ct = String(changeTimes[j]??'0').trim();
  const isModifying = ct !== '0' && ct !== '';
  const isNotIssued = link === '尚未出帳' || String(amt).includes('#N/A');
  if (isNotIssued) anyNotIssued = true;
  if (isModifying) anyModifying = true;
  if (!isNotIssued && !isModifying) { downloadable.push(clients[j]); if (!isNaN(parseFloat(amt))) total += parseFloat(amt); }
  const t = parseMs(st); times.push(t); if (t > latestMs) latestMs = t;
}

const bubbles = [];
let downloadBtn;
if (anyNotIssued) downloadBtn = { type: 'button', action: { type: 'postback', label: '尚未出帳，無法下載', data: 'action=bill_not_ready' }, style: 'primary', color: '#888888' };
else if (anyModifying) downloadBtn = { type: 'button', action: { type: 'postback', label: '⚠️ 帳單修改中 (暫不可下載)', data: 'action=bill_not_ready' }, style: 'primary', color: '#888888' };
else downloadBtn = { type: 'button', action: { type: 'postback', label: '下載全部帳單', data: `action=download_bill&clients=${downloadable.join(',')}`, displayText: '正在下載帳單，請稍候...' }, style: 'primary', color: '#1DB446' };

bubbles.push({
  type: 'bubble', size: 'mega',
  header: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: '🔔 帳單通知', weight: 'bold', size: 'xl', color: '#111111' }] },
  body: { type: 'box', layout: 'vertical', spacing: 'md', contents: [
    { type: 'text', text: '請協助核對帳單，如有錯誤請儘速告知修正：', wrap: true, size: 'md', color: '#111111' },
    { type: 'separator', margin: 'md' },
    { type: 'text', text: '請點下方按鈕下載帳單明細', size: 'sm', color: '#666666', margin: 'md' }
  ] },
  footer: { type: 'box', layout: 'vertical', contents: [downloadBtn] }
});

const pageSize = 4;
for (let i = 0; i < clients.length; i += pageSize) {
  const batch = clients.slice(i, i + pageSize);
  const isLast = (i + pageSize) >= clients.length;
  const rows = [];
  batch.forEach((name, idx) => {
    const ri = i + idx;
    const amt = amounts[ri];
    const st = String(statuses[ri]||'').trim();
    const link = String(links[ri]||'').trim();
    const ct = String(changeTimes[ri]??'0').trim();
    const isNI = link === '尚未出帳' || String(amt).includes('#N/A');
    const isM = ct !== '0' && ct !== '';
    const t = times[ri];
    const isNewest = latestMs > 0 && t > 0 && (latestMs - t) <= 120000;
    let dn = name || '未知公司';
    if (clients.length > 1 && isNewest) dn = `✨ ${dn}`;
    let box = [];
    if (isNI) { box = [{ type: 'text', text: dn, weight: 'bold', size: 'lg', color: '#111111', wrap: true }, { type: 'text', text: '該用戶尚未出帳', size: 'sm', color: '#999999', margin: 'xs', style: 'italic' }]; }
    else if (isM) { box = [{ type: 'text', text: dn, weight: 'bold', size: 'lg', color: '#E67E22', wrap: true }, { type: 'text', text: '⏳ 帳單修改中，請稍候', size: 'sm', color: '#E67E22', weight: 'bold', style: 'italic', margin: 'xs' }]; }
    else { box = [{ type: 'text', text: dn, weight: 'bold', size: 'lg', color: isNewest ? '#E67E22' : '#111111', wrap: true }, { type: 'text', text: `金額：${formatPrice(amt)}${st ? '  ' + st : ''}`, size: 'sm', color: isNewest ? '#E67E22' : '#111111', weight: 'bold', margin: 'xs' }]; }
    rows.push({ type: 'box', layout: 'vertical', margin: 'lg', spacing: 'xs', contents: box });
  });
  if (isLast) {
    rows.push({ type: 'separator', margin: 'xl', color: '#eeeeee' });
    rows.push({ type: 'text', text: '合計總金額', size: 'sm', color: '#888888', align: 'end', margin: 'md' });
    rows.push({ type: 'text', text: `NT$ ${formatPrice(total)}`, size: 'xxl', weight: 'bold', color: '#E63946', align: 'end', adjustMode: 'shrink-to-fit' });
  }
  const bubble = { type: 'bubble', size: 'mega', header: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: clients.length > pageSize ? `📋 帳單總覽 (${Math.floor(i/pageSize)+1})` : '📋 帳單總覽', weight: 'bold', size: 'xl', color: '#111111' }] }, body: { type: 'box', layout: 'vertical', contents: rows } };
  if (isLast) {
    const ba = (bankAccountRaw || '暫無帳號資訊').replace(/(北中壢分行)[\s\u3000]*/g, '$1\n');
    bubble.footer = { type: 'box', layout: 'vertical', contents: [{ type: 'box', layout: 'vertical', backgroundColor: '#F7F7F7', paddingAll: 'md', cornerRadius: 'sm', action: { type: 'clipboard', clipboardText: bankAccountRaw || ba }, contents: [{ type: 'text', text: '🏦 匯款帳號', size: 'sm', color: '#888888', weight: 'bold' }, { type: 'text', text: ba, size: 'lg', color: '#111111', weight: 'bold', wrap: true, margin: 'xs' }] }] };
  }
  bubbles.push(bubble);
}

return [{ json: { flexJsonString: JSON.stringify({ type: 'carousel', contents: bubbles }) } }];

const input = items[0].json;
const clients = input['客戶名稱'];
const links = input['加買發票連結'];
const userId = $('Line Messaging Trigger').first().json.source.userId;
const buttons = clients.map((name, i) => {
  const link = links[i];
  const uri = link.includes('?') ? `${link}&uid=${userId}` : `${link}?uid=${userId}`;
  return { type: 'button', action: { type: 'uri', label: name, uri }, style: 'primary', margin: 'sm' };
