const flex = { type: 'bubble', header: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: '📋 加買發票申請', weight: 'bold', size: 'lg', color: '#1DB446' }] }, body: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: '請選擇對應的單位進行填寫：', size: 'sm', color: '#666666', wrap: true, margin: 'md' }, ...buttons] }, footer: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: '如誤按請忽略此訊息', size: 'sm', color: '#FF0000', align: 'center', weight: 'bold' }] } };
return { flexJsonString: JSON.stringify(flex) };

const input = items[0].json;
const clients = Array.isArray(input.client_name) ? input.client_name : [input.client_name];
const baseLinks = Array.isArray(input.extra_invoice_link) ? input.extra_invoice_link : [input.extra_invoice_link];
const userId = $node['Line Messaging Trigger'].json.source.userId;
const buttons = clients.map((name, i) => {
  const link = baseLinks[i] || '';
  const uri = link.includes('?') ? `${link}&uid=${userId}` : `${link}?uid=${userId}`;
  return { type: 'button', action: { type: 'uri', label: String(name).substring(0, 40), uri }, style: 'primary', margin: 'md', color: '#00B900' };
});
const flex = { type: 'bubble', header: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: '📋 加買發票申請', weight: 'bold', size: 'lg', color: '#1DB446' }] }, body: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: '請選擇對應的單位進行填寫：', size: 'md', color: '#666666', wrap: true, margin: 'none' }, { type: 'box', layout: 'vertical', margin: 'lg', spacing: 'sm', contents: buttons }] }, footer: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: '如誤按請直接忽略此訊息', size: 'md', color: '#FF0000', align: 'center' }] } };
return { flexJsonString: JSON.stringify(flex) };

const items = $input.all();
if (items.length === 0) return [];
const replyToken = $('Line Messaging Trigger').first().json.replyToken || '';
const first = items[0].json;
const companyName = first['客戶名稱'] || '';
const driveLink = first['雲端資料夾'] || '';
const m = driveLink.match(/[-\w]{25,}/);
const folderId = m ? m[0] : '';
return [{ json: { replyToken, folder_id: folderId, folder_name: companyName, company_id: folderId, company_name: companyName, raw_search_key: `folder_id=${folderId}&folder_name=${companyName}` } }];

const items = $input.all();
let replyToken = '', currentFolderName = '', currentFolderId = '', companyId = '', companyName = '';
function tryGetNode(n) { try { const d = $(n).first().json; if (d && (d.company_name || d.folder_id || d.folder_name || d.replyToken)) return d; } catch(e) {} return null; }
const p = tryGetNode('Call 客戶資料夾') || tryGetNode('Code in JavaScript9') || tryGetNode('Code in JavaScript8') || ($input.first() ? $input.first().json : {});
replyToken = p.replyToken || '';
companyName = p.company_name || p.folder_name || '客戶資料';
currentFolderName = p.folder_name || companyName;
if (currentFolderName === '雲端資料夾') currentFolderName = companyName;
currentFolderId = p.folder_id || '';
companyId = p.company_id || currentFolderId;
function formatFileName(n) {
  if (!n) return '';
  let d = n;
  const tm = d.match(/^(\d{3})(\d{2})_\d+_營業人銷售額與稅額申報書\((\d{3})\)/);
  if (tm) { const pm = {'02':'01-02月','04':'03-04月','06':'05-06月','08':'07-08月','10':'09-10月','12':'11-12月'}; const ext = d.substring(d.lastIndexOf('.')); return `${tm[1]}年${pm[tm[2]]||tm[2]+'期'}${tm[3]}表${ext}`; }
  d = d.replace(/^[A-Z]\d{2}-?/i, '').replace(/\([^)]*\d{8}[^)]*\)/g, '').replace(/_?\d{8}_?/g, '').replace(/--+/g, '-');
  return d;
}
function buildOpenBtn(id) { return { type: 'button', action: { type: 'uri', label: '📂 開啟雲端資料夾', uri: `https://drive.google.com/drive/folders/${id}` }, style: 'link', height: 'sm' }; }
function buildBackFooter(cid, cn, cfid) { return { type: 'box', layout: 'vertical', contents: [buildOpenBtn(cfid), { type: 'button', action: { type: 'postback', label: `🔙 返回 ${cn}`, data: `folder_id=${cid}&folder_name=${cn}&company_id=${cid}&company_name=${cn}`, displayText: `🔙 返回 ${cn}` }, style: 'link', height: 'sm' }] }; }
function buildNotFoundFooter(cfid) { return { type: 'box', layout: 'vertical', contents: [buildOpenBtn(cfid), { type: 'button', action: { type: 'postback', label: '找不到文件', data: '/檔案不存在。', displayText: '找不到我要的文件' }, style: 'primary', color: '#FF4B4B', height: 'sm' }] }; }
const fileItems = [], folderItems = [];
for (const it of items) { const f = it.json; if (!f || !f.id || !f.name) continue; const mt = f.mimeType || ''; const isF = mt === 'application/vnd.google-apps.folder' || mt.includes('folder') || (!f.name.includes('.') && !f.webViewLink); if (isF) folderItems.push(f); else fileItems.push(f); }
fileItems.sort((a, b) => (a.name || '').localeCompare(b.name || '', 'zh-Hant', { numeric: true }));
folderItems.sort((a, b) => (a.name || '').localeCompare(b.name || '', 'zh-Hant', { numeric: true }));
const isAtRoot = currentFolderId === companyId;
const headerTitle = (!isAtRoot && currentFolderName && currentFolderName !== companyName) ? `${companyName}\n${currentFolderName}` : companyName;
const bubbles = [];
if (fileItems.length > 0) {
  const fileContents = fileItems.map(f => {
    let u = ''; const mt = f.mimeType || '';
    if (mt.includes('google-apps.document')) u = `https://docs.google.com/document/d/${f.id}/export?format=pdf&openExternalBrowser=1`;
    else if (mt.includes('google-apps.spreadsheet')) u = `https://docs.google.com/spreadsheets/d/${f.id}/export?format=xlsx&openExternalBrowser=1`;
    else u = `https://drive.google.com/uc?export=download&id=${f.id}&openExternalBrowser=1`;
    return { type: 'box', layout: 'horizontal', margin: 'md', paddingAll: 'sm', action: { type: 'uri', uri: u }, contents: [{ type: 'text', text: `📄 ${formatFileName(f.name)}`, wrap: true, color: '#0068FF', size: 'md' }] };
  });
  const fb = { type: 'bubble', header: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: '📥 檔案點擊下載', weight: 'bold', size: 'xs', color: '#1DB446' }, { type: 'text', text: headerTitle, weight: 'bold', size: 'lg', color: '#333333', wrap: true, margin: 'xs' }] }, body: { type: 'box', layout: 'vertical', contents: fileContents } };
  if (!isAtRoot) fb.footer = buildBackFooter(companyId, companyName, currentFolderId);
  bubbles.push(fb);
}
if (folderItems.length > 0) {
  const folderContents = folderItems.map(f => ({ type: 'box', layout: 'horizontal', margin: 'sm', paddingAll: 'sm', backgroundColor: '#F5F5F5', cornerRadius: 'md', action: { type: 'postback', data: `folder_id=${f.id}&folder_name=${f.name}&company_id=${companyId}&company_name=${companyName}`, displayText: `📁 開啟 ${f.name}` }, contents: [{ type: 'text', text: `📁 ${f.name}`.substring(0, 20), wrap: true, color: '#555555', size: 'md' }] }));
  const fb = { type: 'bubble', header: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: '📁 分類資料夾', weight: 'bold', size: 'xs', color: '#1DB446' }, { type: 'text', text: headerTitle, weight: 'bold', size: 'lg', color: '#333333', wrap: true, margin: 'xs' }] }, body: { type: 'box', layout: 'vertical', contents: folderContents } };
  fb.footer = isAtRoot ? buildNotFoundFooter(currentFolderId) : buildBackFooter(companyId, companyName, currentFolderId);
  bubbles.push(fb);
}
if (bubbles.length === 0) bubbles.push({ type: 'bubble', body: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: '（此資料夾內目前沒有任何檔案或資料夾）', color: '#888888', align: 'center', size: 'sm', wrap: true, margin: 'md' }] } });
const flexContent = bubbles.length === 1 ? bubbles[0] : { type: 'carousel', contents: bubbles };
return [{ json: { replyToken, flexObject: flexContent } }];

const item = $('Line Messaging Trigger').first().json;
const replyToken = item.replyToken || item.body?.events?.[0]?.replyToken || '';
const postbackData = item.postback?.data || item.body?.events?.[0]?.postback?.data || item.data || item.text || '';
let folderId = '', folderName = '', companyId = '', companyName = '';
if (typeof postbackData === 'string' && postbackData.includes('folder_id=')) {
  folderId = postbackData.split('folder_id=')[1]?.split('&')[0] || '';
  if (postbackData.includes('folder_name=')) { const raw = postbackData.split('folder_name=')[1]?.split('&')[0] || ''; try { folderName = decodeURIComponent(raw); } catch(e) { folderName = raw; } }
}
if (typeof postbackData === 'string' && postbackData.includes('company_id=')) {
  companyId = postbackData.split('company_id=')[1]?.split('&')[0] || '';
  if (postbackData.includes('company_name=')) { const raw = postbackData.split('company_name=')[1]?.split('&')[0] || ''; try { companyName = decodeURIComponent(raw); } catch(e) { companyName = raw; } }
}
if (!companyId) { companyId = folderId; companyName = folderName; }
return [{ json: { replyToken, folder_id: folderId, folder_name: folderName, company_id: companyId, company_name: companyName, raw_search_key: postbackData } }];

const items = $input.all();
const triggerDataList = $('Line Messaging Trigger').all();
const httpDataList = $('HTTP Request3').all();
const sheetDataList = $('Get row(s) in sheet5').all();
const now = new Date();
const tz = 'Asia/Taipei';
const day = new Intl.DateTimeFormat('zh-TW', { year: 'numeric', month: '2-digit', day: '2-digit', timeZone: tz }).format(now).replace(/\//g, '-');
return items.map((item, i) => {
  const t = triggerDataList[i]?.json || triggerDataList[0]?.json || {};
  const msg = t.message || {};
  const uid = t.source?.userId || '';
  const mt = msg.type || 'file';
  const bin = httpDataList[i]?.binary || item.binary || httpDataList[0]?.binary || {};
  let dn = uid;
  try { const s = sheetDataList[i]?.json || sheetDataList[0]?.json; if (s) dn = s['C:displayName'] || s.displayName || uid; } catch(e) {}
  const tm = new Intl.DateTimeFormat('zh-TW', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false, timeZone: tz }).format(now).replace(/:/g, '');
  const sfx = items.length > 1 ? `_${i+1}` : '';
  let fn = msg.fileName;
  if (!fn) { if (mt === 'image') fn = `LINE_Image_${tm}${sfx}.jpg`; else if (mt === 'audio') fn = `LINE_Voice_${tm}${sfx}.m4a`; else fn = `LINE_File_${tm}${sfx}.dat`; }
  return { json: { dayFolderName: day, fileName: `${dn}_${fn}`, originalFileName: fn, userName: dn, userId: uid, msgType: mt }, binary: bin };
});

const items = $input.all();
const codeDataList = $('Code in JavaScript6').all();
return items.map((item, i) => {
  const cd = codeDataList[i]?.json || codeDataList[0]?.json || {};
  const mj = item.json || {};
  const aiText = mj.candidates?.[0]?.content?.parts?.[0]?.text || mj.content?.parts?.[0]?.text || mj.text || '（目前無辨識文字）';
  const raw = cd.fileName || mj.name || '憑證檔案.dat';
  const txt = raw.replace(/\.[^/.]+$/, '') + '_辨識摘要.txt';
  const buf = Buffer.from(aiText, 'utf-8');
  return { json: { ...mj, txtFileName: txt, aiText }, binary: { data: { data: buf.toString('base64'), mimeType: 'text/plain', fileName: txt, fileExtension: 'txt' } } };
});

return $input.all().map(item => {
  let p = item.json.systemPrompt || '';
  p = p.replace(/^`+|`+$/g, '').trim();
  const b = item.binary || {};
  if (!b.data && Object.keys(b).length > 0) { const k = Object.keys(b)[0]; b.data = b[k]; }
  return { json: { ...item.json, systemPrompt: p }, binary: b };
});

function getSafe(n) { try { return $(n).all(); } catch(e) { return []; } }
const codeDataList = getSafe('Code in JavaScript6');
const driveOriginalList = getSafe('Upload file1');
const driveTxtList = getSafe('Upload txt');
const txtGenList = getSafe('生成 TXT 檔');
const triggers = getSafe('Line Messaging Trigger');
const first = triggers[0]?.json || {};
const replyToken = first.replyToken || '';
const total = codeDataList.length;
if (total === 0) return [];
const unrec = txtGenList.some(i => (i.json?.aiText || '').includes('無法辨識'));
const chat = txtGenList.some(i => (i.json?.aiText || '').includes('對話截圖'));
if (unrec || chat) return [];
const targets = ['060508003687','060508308968'];
const heads = ['0605'];
const tails = ['03687','08968'];
const hasTransfer = txtGenList.some(i => {
  const t = i.json?.aiText || '';
  const c = t.replace(/[\s\-\_\(\)]/g, '');
  if (targets.some(a => c.includes(a))) return true;
  return tails.some(tl => { if (!c.includes(tl)) return false; if (heads.some(h => c.includes(h))) return true; const idx = c.indexOf(tl); const b = c.slice(Math.max(0, idx-6), idx); return /^[\dO○Ｏ*Xx•]+$/.test(b) && b.length >= 3; });
});
let msgs = [];
if (hasTransfer) {
  msgs.push({ type: 'text', text: '✅ 已收到您的匯款資訊！\n對帳需人工核對（非即時），完成後將另行通知，感謝配合！' });
} else {
  const bubbles = codeDataList.map((c, i) => {
    const cd = c.json || {};
    const dO = driveOriginalList[i]?.json || {};
    const dT = driveTxtList[i]?.json || {};
    const tG = txtGenList[i]?.json || {};
    const aiText = tG.aiText || '（暫不提供 AI 解析）';
    const label = cd.originalFileName || `檔案_${i+1}`;
    const oUrl = dO.webViewLink || dO.webContentLink || '';
    const tUrl = dT.webViewLink || dT.webContentLink || '';
    const b = { type: 'bubble', size: 'kilo', header: { type: 'box', layout: 'horizontal', backgroundColor: '#F7F9FA', contents: [{ type: 'text', text: total === 1 ? '憑證辨識摘要' : `項目 (${i+1}/${total})`, weight: 'bold', size: 'sm', color: '#1DB446' }, { type: 'text', text: '已存檔 ☁️', size: 'xs', color: '#888888', align: 'end', gravity: 'center' }] }, body: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: cd.msgType === 'audio' ? `🎙️ ${label}` : `📁 ${label}`, weight: 'bold', size: 'md', color: '#0066CC', wrap: true }, { type: 'separator', margin: 'md' }, { type: 'text', text: aiText, size: 'xs', color: '#333333', wrap: true, margin: 'md' }] } };
    const fl = [];
    if (tUrl) fl.push({ type: 'text', text: '📄 TXT', color: '#0066CC', size: 'xs', align: 'center', decoration: 'underline', action: { type: 'uri', uri: tUrl } });
    if (oUrl) fl.push({ type: 'text', text: '📂 原檔', color: '#0066CC', size: 'xs', align: 'center', decoration: 'underline', action: { type: 'uri', uri: oUrl } });
    if (fl.length) b.footer = { type: 'box', layout: 'horizontal', contents: fl };
